catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    var ga = new GlideAjax('x_946454_food_de_0.PinCodeHelper');
    ga.addParam('sysparm_name', 'getMenuDetails');
    ga.addParam('sysparm_menu_name_sys_id', newValue);
    alert(newValue);

    ga.getXML(getMenuDetails);

    function getMenuDetails(response) {
        var ans = response.responseXML.documentElement.getAttribute("answer");
        alert(ans);
        var res = JSON.parse(ans);
        if (res) {
            g_form.setValue('ingredients', res.ingredients + '');
            g_form.setValue('price', res.price + '');
        } else {
            g_form.setValue('ingredients', 0);
            g_form.setValue('price', 0);

        }
    }

    //Type appropriate comment here, and begin script below

}
